import { useState, useEffect, useRef } from 'react';
import { Link } from 'react-router-dom';
import { recipeApi, searchApi, rankingApi } from '../api';

export default function RecipeListPage() {
  const [recipes, setRecipes] = useState([]);
  const [ranking, setRanking] = useState([]);
  const [keyword, setKeyword] = useState('');
  const [search, setSearch] = useState('');
  const [suggestions, setSuggestions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [tab, setTab] = useState('all'); // 'all' | 'ranking'
  const debounceRef = useRef(null);

  useEffect(() => {
    setLoading(true);
    recipeApi.getList({ keyword: search || undefined, size: 12 })
      .then(res => setRecipes(res.data.content))
      .catch(console.error)
      .finally(() => setLoading(false));
  }, [search]);

  useEffect(() => {
    rankingApi.getTop()
      .then(res => setRanking(res.data))
      .catch(() => {});
  }, []);

  const handleKeywordChange = (e) => {
    const val = e.target.value;
    setKeyword(val);
    clearTimeout(debounceRef.current);
    if (val.trim().length < 1) { setSuggestions([]); return; }
    debounceRef.current = setTimeout(async () => {
      try {
        const res = await searchApi.autocomplete(val.trim());
        setSuggestions(res.data);
      } catch { setSuggestions([]); }
    }, 200);
  };

  const handleSuggestionClick = (s) => {
    setKeyword(s);
    setSuggestions([]);
    setSearch(s);
  };

  const displayRecipes = tab === 'ranking' ? ranking : recipes;

  return (
    <div>
      {/* 검색창 */}
      <div style={{ position: 'relative', display: 'flex', gap: 8, marginBottom: 20 }}>
        <div style={{ flex: 1, position: 'relative' }}>
          <input
            style={inputStyle}
            placeholder="레시피 검색... (자동완성 지원)"
            value={keyword}
            onChange={handleKeywordChange}
            onKeyDown={e => { if (e.key === 'Enter') { setSearch(keyword); setSuggestions([]); } }}
            onBlur={() => setTimeout(() => setSuggestions([]), 150)}
          />
          {suggestions.length > 0 && (
            <ul style={suggestStyle}>
              {suggestions.map((s, i) => (
                <li key={i} style={suggestItem} onMouseDown={() => handleSuggestionClick(s)}>
                  🔍 {s}
                </li>
              ))}
            </ul>
          )}
        </div>
        <button onClick={() => { setSearch(keyword); setSuggestions([]); }} style={searchBtn}>검색</button>
      </div>

      {/* 탭 */}
      <div style={{ display: 'flex', gap: 0, marginBottom: 20, borderBottom: '2px solid #eee' }}>
        {[['all', '전체 레시피'], ['ranking', '🔥 인기 랭킹']].map(([key, label]) => (
          <button key={key} onClick={() => setTab(key)} style={{
            padding: '8px 18px', border: 'none', background: 'none', cursor: 'pointer',
            fontWeight: tab === key ? 700 : 400, fontSize: 14,
            borderBottom: tab === key ? '2px solid #111' : '2px solid transparent',
            marginBottom: -2, color: tab === key ? '#111' : '#888',
          }}>{label}</button>
        ))}
      </div>

      {/* 랭킹 뱃지 */}
      {tab === 'ranking' && ranking.length === 0 && (
        <p style={{ color: '#888', fontSize: 13 }}>아직 조회 데이터가 없습니다. 레시피를 조회하면 랭킹이 쌓여요!</p>
      )}

      {loading && tab === 'all' ? (
        <p style={{ color: '#888' }}>불러오는 중...</p>
      ) : (
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(260px, 1fr))', gap: 20 }}>
          {displayRecipes.map((recipe, idx) => (
            <Link key={recipe.id} to={`/recipes/${recipe.id}`} style={{ textDecoration: 'none', color: 'inherit' }}>
              <div style={cardStyle}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                  <h3 style={{ margin: 0, fontSize: 16, fontWeight: 600, flex: 1, marginRight: 8 }}>{recipe.title}</h3>
                  <div style={{ display: 'flex', gap: 4, flexShrink: 0 }}>
                    {tab === 'ranking' && (
                      <span style={{ ...forkBadge, background: idx < 3 ? '#111' : '#888' }}>
                        {idx === 0 ? '🥇' : idx === 1 ? '🥈' : idx === 2 ? '🥉' : `#${idx + 1}`}
                      </span>
                    )}
                    {recipe.forkedFromId && <span style={forkBadge}>Fork</span>}
                  </div>
                </div>
                <p style={{ color: '#777', fontSize: 13, marginTop: 8, marginBottom: 12 }}>
                  {recipe.description?.slice(0, 60) || '설명 없음'}
                </p>
                <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
                  <span style={badge}>{recipe.category}</span>
                  {recipe.difficulty && <span style={badge}>{recipe.difficulty}</span>}
                  {recipe.cookingTime && <span style={badge}>{recipe.cookingTime}분</span>}
                </div>
                <p style={{ fontSize: 12, color: '#aaa', marginTop: 10 }}>by {recipe.ownerUsername}</p>
              </div>
            </Link>
          ))}
          {displayRecipes.length === 0 && (
            <p style={{ color: '#888', gridColumn: '1/-1' }}>레시피가 없습니다.</p>
          )}
        </div>
      )}
    </div>
  );
}

const inputStyle = { width: '100%', padding: '10px 14px', border: '1px solid #ddd', borderRadius: 6, fontSize: 14, boxSizing: 'border-box' };
const searchBtn = { padding: '10px 20px', background: '#111', color: '#fff', border: 'none', borderRadius: 6, cursor: 'pointer' };
const suggestStyle = { position: 'absolute', top: '100%', left: 0, right: 0, background: '#fff', border: '1px solid #ddd', borderRadius: 6, zIndex: 100, margin: 0, padding: 0, listStyle: 'none', boxShadow: '0 4px 12px rgba(0,0,0,0.1)' };
const suggestItem = { padding: '10px 14px', cursor: 'pointer', fontSize: 14, borderBottom: '1px solid #f0f0f0' };
const cardStyle = { border: '1px solid #eee', borderRadius: 10, padding: 18, cursor: 'pointer', transition: 'box-shadow .15s' };
const badge = { background: '#f0f0f0', padding: '3px 8px', borderRadius: 4, fontSize: 11, color: '#555' };
const forkBadge = { background: '#111', color: '#fff', padding: '2px 7px', borderRadius: 4, fontSize: 11 };
